class T(unittest.TestCase):
    def test_case(self):
        class Countdown():
            def __init__(me, n): me.n = n
            def __iter__(me): return me
            def __next__(me):
                if me.n <= 0: raise StopIteration()
                me.n = me.n - 1
                return me.n + 1
        self.assertEqual(list(Countdown(3)), [3, 2, 1])

