class T(unittest.TestCase):
    def test_case(self):
        def g():
            yield 1
            return 99
        def drive():
            it = g()
            out = []
            out.append(next(it))
            try:
                next(it)
            except StopIteration as s:
                out.append(s.value)
            return out
        self.assertEqual(drive(), [1, 99])

class T(unittest.TestCase):
    def test_case(self):
        def probe():
            res = []
            try:
                raise ValueError('inner')
            except ValueError as e:
                try:
                    raise RuntimeError('outer') from e
                except RuntimeError as r2:
                    res.append(r2.__cause__.__class__.__name__)
                    res.append(r2.__context__.__class__.__name__)
            return res
        self.assertEqual(probe(), ['RuntimeError' if False else 'ValueError', 'ValueError'])

