                return False
            except TypeError:
                return True
        self.assertEqual(probe(), True)

class T(unittest.TestCase):
    def test_case(self):
        def probe():
            seen = []
            class Ctx():
                def __enter__(me): return me
                def __exit__(me, et, ev, tb):
                    seen.append(et.__name__)
                    return True
            with Ctx():
                raise ValueError('x')
            return seen
        self.assertEqual(probe(), ['ValueError'])

